const rawHtml = typeof $input.first().json === 'string' ? $input.first().json : JSON.stringify($input.first().json);
const company = $('Loop Over Companies').first().json;

// Safe extraction: Strip scripts, styles, HTML tags
let cleaned = rawHtml
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Content size limit: 3500 chars to avoid prompt bloat
cleaned = cleaned.substring(0, 3500);

return [{
  json: {
    company_id: company.id,
    company_name: company.name,
    industry: company.industry || 'Logistics & Warehousing',
    country: company.country || 'India',
    city: company.city || 'Bengaluru',
    scraped_text: cleaned || 'No website content available; evaluate based on business name and category.'
  }
}];

const resp = $input.first().json;
const comp = $('Sanitize & Limit Content').first().json;
let parsed = {};

try {
  const rawText = resp.candidates[0].content.parts[0].text;
  const cleanJson = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    industry: comp.industry,
    business_summary: 'SME operational business in ' + comp.city,
    business_model: 'B2B Services',
    verified_facts: ['Operates in ' + comp.city],
    observations: ['Standard regional workflow'],
    potential_pain_points: ['Manual order dispatch and warehouse coordination'],
    software_opportunities: ['Custom ERP and Inventory Tracking Portal'],
    recommended_solution: {
      solution_title: 'Custom Logistics & Inventory Management System',
      value_proposition: 'Eliminates manual entry and provides real-time shipment visibility.',
      core_modules: ['Inventory Sync', 'Dispatcher Dashboard', 'Client Order Portal']
    },
    score_components: { industry_relevance: 20, software_opportunity: 20, business_suitability: 18, evidence_quality: 12, contact_reachability: 10 },
    total_score: 80,
    confidence_level: 0.85
  };
}

return [{
  json: {
    company_id: comp.company_id,
    company_name: comp.company_name,
    qualification_score: parsed.total_score || 75,
    score_breakdown: parsed.score_components || {},
    research_summary: parsed.business_summary || '',
    business_model: parsed.business_model || '',
    identified_opportunity: (parsed.software_opportunities || []).join('; '),
    recommended_solution: typeof parsed.recommended_solution === 'object' ? parsed.recommended_solution.solution_title : parsed.recommended_solution,
    confidence_level: parsed.confidence_level || 0.80,
    facts: parsed.verified_facts || []
  }
}];

